sealed interface Tree
data class Leaf(val text: String) : Tree
data class Branch(val kids: List<Tree>) : Tree

data class Frame(val parent: Branch, val index: Int)      // one hole per level
data class Loc(val focus: Tree, val path: List<Frame>)

fun up(l: Loc): Loc {                                     // rebuild the parent once
    val f = l.path.last()
    val kids = f.parent.kids.toMutableList().also { it[f.index] = l.focus }
    return Loc(f.parent.copy(kids = kids), l.path.dropLast(1))
}
